package org.brightstats.desktop;
import com.google.gson.*;import java.nio.charset.StandardCharsets;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.*;import org.brightstats.report.ReproducibilityBundle;
/** Explicit content review precedes a local archive save; no network or execution. */
final class ReproducibilityDialog {
 final Dialog<Void> dialog=new Dialog<>();final CheckBox data=new CheckBox("Include working observations and original source/history"),report=new CheckBox("Include complete current report (contains its historical data and case-level outputs)"),reviewed=new CheckBox("I have reviewed the selected archive contents");final ComboBox<String> entries=new ComboBox<>();final TextArea preview=new TextArea(),cautions=new TextArea();final Label summary=new Label();ReproducibilityBundle.Plan plan;final JsonObject project,analysis;
 ReproducibilityDialog(Window owner,JsonObject source,JsonObject currentReport){project=source.deepCopy();analysis=currentReport==null?null:currentReport.deepCopy();dialog.initOwner(owner);dialog.setTitle("Review reproducibility bundle");dialog.setResizable(true);preview.setEditable(false);preview.setWrapText(false);preview.setPrefRowCount(16);preview.setStyle("-fx-font-family:monospace;");cautions.setEditable(false);cautions.setWrapText(true);cautions.setPrefRowCount(5);report.setDisable(true);report.setWrapText(true);data.setWrapText(true);summary.setWrapText(true);entries.setMaxWidth(Double.MAX_VALUE);entries.setAccessibleText("Exact archive entry to review");entries.valueProperty().addListener((o,a,b)->showEntry());data.setOnAction(e->{report.setDisable(!data.isSelected()||analysis==null);if(!data.isSelected())report.setSelected(false);refresh();});report.setOnAction(e->refresh());VBox content=new VBox(9,new Label("Local ZIP archive — no programs are installed or run"),data,report,summary,cautions,entries,preview,reviewed);content.setStyle("-fx-padding:14;");content.setPrefSize(860,690);VBox.setVgrow(preview,Priority.ALWAYS);dialog.getDialogPane().setContent(content);ButtonType save=new ButtonType("Save bundle",ButtonBar.ButtonData.OK_DONE);dialog.getDialogPane().getButtonTypes().addAll(save,ButtonType.CANCEL);var saveButton=dialog.getDialogPane().lookupButton(save);saveButton.disableProperty().bind(reviewed.selectedProperty().not());saveButton.addEventFilter(javafx.event.ActionEvent.ACTION,e->{e.consume();FileChooser chooser=new FileChooser();chooser.setTitle("Save reviewed reproducibility bundle");chooser.setInitialFileName("bright-stats-reproducibility.zip");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("Reproducibility archive","*.zip"));var selected=chooser.showSaveDialog(dialog.getDialogPane().getScene().getWindow());if(selected==null)return;try{ReproducibilityBundle.write(selected.toPath(),plan);dialog.close();}catch(Exception problem){Alert error=new Alert(Alert.AlertType.ERROR,"Archive was not saved: "+problem.getMessage(),ButtonType.OK);error.initOwner(dialog.getDialogPane().getScene().getWindow());error.showAndWait();}});refresh();}
 void refresh(){reviewed.setSelected(false);plan=ReproducibilityBundle.preview(project,analysis,new ReproducibilityBundle.Options(data.isSelected(),report.isSelected()));entries.getItems().setAll(plan.entries().stream().map(ReproducibilityBundle.Entry::name).toList());entries.getItems().add("manifest.json");entries.getSelectionModel().selectFirst();summary.setText(plan.entries().size()+" reviewed files + checksum manifest. Labels/settings may still contain private information; this does not certify that content is safe to publish.");cautions.setText(String.join("\n\n",plan.cautions()));showEntry();}
 void showEntry(){String name=entries.getValue();if(name==null)return;if(name.equals("manifest.json")){preview.setText(new GsonBuilder().setPrettyPrinting().create().toJson(ReproducibilityBundle.manifest(plan)));return;}for(var entry:plan.entries())if(entry.name().equals(name)){preview.setText(new String(entry.bytes(),StandardCharsets.UTF_8));preview.positionCaret(0);break;}}
 static void show(Window owner,JsonObject source,JsonObject report){new ReproducibilityDialog(owner,source,report).dialog.showAndWait();}
}
